use serde::{Deserialize, Serialize};

#[cfg(doc)]
use crate::{Account, Collection, Item};

mod shared;

pub use self::shared::*;

/// An [Extension] is a generic object that can be used to extend the [Item] or [Account] with
/// additional information.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "name", rename_all = "kebab-case")]
#[non_exhaustive]
pub enum Extension<E = ()> {
    /// Defines a sharing relationship of [`Collection`] or [`Item`] between different user
    /// accounts or groups.
    Shared(SharedExtension),
    #[serde(untagged)]
    /// External extensions defined by the implementor of this crate.
    External(E),
    /// Unknown extension
    #[serde(untagged)]
    Unknown(serde_json::Value),
}

use data_encoding::{Specification, BASE32_NOPAD, BASE64URL, BASE64URL_NOPAD};
use serde::{Deserialize, Serialize};

/// Base64URL encoded data
#[derive(Debug, Serialize, Deserialize, Clone, Hash, PartialEq, Eq)]
#[serde(try_from = "&str", into = "String")]
pub struct B64Url(Vec<u8>);

impl From<Vec<u8>> for B64Url {
    fn from(src: Vec<u8>) -> Self {
        Self(src)
    }
}
impl From<&[u8]> for B64Url {
    fn from(src: &[u8]) -> Self {
        Self(src.to_vec())
    }
}

impl From<B64Url> for Vec<u8> {
    fn from(src: B64Url) -> Self {
        src.0
    }
}

impl AsRef<[u8]> for B64Url {
    fn as_ref(&self) -> &[u8] {
        &self.0
    }
}

impl From<B64Url> for String {
    fn from(src: B64Url) -> Self {
        String::from(&src)
    }
}
impl From<&B64Url> for String {
    fn from(src: &B64Url) -> Self {
        BASE64URL_NOPAD.encode(&src.0)
    }
}

impl std::fmt::Display for B64Url {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(String::from(self).as_str())
    }
}

/// An error returned when a string is not base64 decodable.
#[derive(Debug)]
pub struct NotB64UrlEncoded;

impl std::fmt::Display for NotB64UrlEncoded {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Data isn't base64url encoded")
    }
}

impl TryFrom<&str> for B64Url {
    type Error = NotB64UrlEncoded;

    fn try_from(value: &str) -> Result<Self, Self::Error> {
        let specs = BASE64URL.specification();
        let padding = specs.padding.unwrap();
        let specs = Specification {
            check_trailing_bits: false,
            padding: None,
            ..specs
        };
        let encoding = specs.encoding().unwrap();
        let sane_string = value.trim_end_matches(padding);
        encoding
            .decode(sane_string.as_bytes())
            .map(Self)
            .map_err(|_| NotB64UrlEncoded)
    }
}

/// Newtype to encode and decode a vector of bytes to and from Base32.
#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
#[serde(try_from = "&str", into = "String")]
pub struct B32(Vec<u8>);

impl From<Vec<u8>> for B32 {
    fn from(src: Vec<u8>) -> Self {
        Self(src)
    }
}
impl From<&[u8]> for B32 {
    fn from(src: &[u8]) -> Self {
        Self(src.to_vec())
    }
}

impl From<B32> for Vec<u8> {
    fn from(src: B32) -> Self {
        src.0
    }
}

impl AsRef<[u8]> for B32 {
    fn as_ref(&self) -> &[u8] {
        &self.0
    }
}

impl From<B32> for String {
    fn from(src: B32) -> Self {
        BASE32_NOPAD.encode(&src.0)
    }
}

/// The string was not base32 encoded
#[derive(Debug)]
pub struct NotBase32Encoded;

impl std::fmt::Display for NotBase32Encoded {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Data isn't base32 encoded")
    }
}

impl TryFrom<&str> for B32 {
    type Error = NotBase32Encoded;

    fn try_from(value: &str) -> Result<Self, Self::Error> {
        let symbols = BASE32_NOPAD.specification().symbols;
        let mut sane_string: String = value.to_ascii_uppercase();
        sane_string.retain(|c| symbols.contains(c));
        BASE32_NOPAD
            .decode(sane_string.as_bytes())
            .map(Self)
            .map_err(|_| NotBase32Encoded)
    }
}

use serde::{Deserialize, Serialize};

use crate::{B64Url, Uri};

/// This is an object that describes an appropriate context in which the [Item][crate::Item]'s
/// [crate::Item::credentials] can to be used.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CredentialScope {
    /// This member holds strings which SHOULD follow the Uniform Resource Identifier (URI) syntax
    /// as defined in [RFC3986](https://www.rfc-editor.org/rfc/rfc3986).
    pub urls: Vec<Uri>,
    /// This member defines the android apps that have been validated to be appropriate for the
    /// credentials to be used.
    pub android_apps: Vec<AndroidAppIdCredential>,
}

/// An [AndroidAppIdCredential] contains the information required to verify and identify an
/// [Android](https://www.android.com/) application for automatically filling other credentials
/// associated to the same [Item][crate::Item] as this one.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AndroidAppIdCredential {
    /// The application identifier. A non-normative example of an application identifier is
    /// `"com.example.myapp"`.
    pub bundle_id: String,
    /// The fingerprint of the public certificate used to sign the android application. This member
    /// is OPTIONAL but is highly recommended to be stored for validation during an autofill
    /// operation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub certificate: Option<AndroidAppCertificateFingerprint>,
    /// The [human-palatable](https://www.w3.org/TR/webauthn-3/#human-palatability) name for the
    /// application, this can be fetched from the android system when associating the app to an
    /// item. It is highly recommended for providers to store this name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AndroidAppCertificateFingerprint {
    /// This is the hash of the application's public certificate using the hashing algorithm
    /// defined in [AndroidAppCertificateFingerprint::hash_alg]. The bytes of the hash are
    /// then encoded into base64url directly.
    pub fingerprint: B64Url,
    /// The algorithm used to hash the [AndroidAppCertificateFingerprint::fingerprint]. This SHOULD
    /// be of value [AndroidAppHashAlgorithm].
    pub hash_alg: AndroidAppHashAlgorithm,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
#[non_exhaustive]
pub enum AndroidAppHashAlgorithm {
    Sha256,
    Sha1,
    #[serde(untagged)]
    Other(String),
}

//! Calendar date and month types, backed by either `chrono` or `jiff`.
//!
//! The backing library is selected with cargo features:
//!
//! * `chrono` (default) - [`Month`] and [`NaiveDate`] are re-exports of `chrono::Month` and
//!   `chrono::NaiveDate`.
//! * `jiff` - [`NaiveDate`] is an alias for `jiff::civil::Date` and [`Month`] is a local
//!   compatibility enum, because `jiff` represents months as plain integers.
//!
//! Exactly one of the two features must be enabled. Enable `jiff` by turning off default features:
//!
//! ```toml
//! credential-exchange-format = { version = "0.4", default-features = false, features = ["jiff"] }
//! ```

#[cfg(feature = "chrono")]
pub use chrono::{Month, NaiveDate};

#[cfg(all(feature = "jiff", not(feature = "chrono")))]
pub use self::jiff_impl::{Month, NaiveDate};

#[cfg(not(any(feature = "chrono", feature = "jiff")))]
compile_error!("either the `chrono` or the `jiff` feature must be enabled");

/// Formats a date using the `yyyy-mm-dd` format expected by the `date` field type.
pub(crate) fn date_to_string(date: &NaiveDate) -> String {
    #[cfg(feature = "chrono")]
    {
        date.format("%Y-%m-%d").to_string()
    }
    #[cfg(all(feature = "jiff", not(feature = "chrono")))]
    {
        date.to_string()
    }
}

/// Parses a date written in the `yyyy-mm-dd` format expected by the `date` field type.
pub(crate) fn date_from_str(value: &str) -> Result<NaiveDate, ()> {
    value.parse().map_err(|_| ())
}

/// Returns the month number in the range `1..=12`.
pub(crate) fn month_number(month: Month) -> u8 {
    #[cfg(feature = "chrono")]
    {
        month.number_from_month() as u8
    }
    #[cfg(all(feature = "jiff", not(feature = "chrono")))]
    {
        month.number_from_month()
    }
}

/// Builds a date from its calendar components, used by tests to stay backend agnostic.
#[cfg(test)]
pub(crate) fn date_from_ymd(year: i16, month: u8, day: u8) -> Option<NaiveDate> {
    #[cfg(feature = "chrono")]
    {
        NaiveDate::from_ymd_opt(i32::from(year), u32::from(month), u32::from(day))
    }
    #[cfg(all(feature = "jiff", not(feature = "chrono")))]
    {
        NaiveDate::new(year, month as i8, day as i8).ok()
    }
}

/// `jiff` backed implementations of the public calendar types.
#[cfg(all(feature = "jiff", not(feature = "chrono")))]
mod jiff_impl {
    use core::{error::Error, fmt};

    /// A Gregorian calendar date, backed by [`jiff::civil::Date`].
    pub type NaiveDate = jiff::civil::Date;

    /// A month of the year.
    ///
    /// `jiff` stores months as `i8`s, so this enum mirrors `chrono::Month`, including its
    /// 0-based discriminants, to keep this crate's public API identical regardless of which
    /// backend is selected. Use [`Month::number_from_month`] for the 1-based month number.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    #[repr(u8)]
    #[non_exhaustive]
    pub enum Month {
        January = 0,
        February = 1,
        March = 2,
        April = 3,
        May = 4,
        June = 5,
        July = 6,
        August = 7,
        September = 8,
        October = 9,
        November = 10,
        December = 11,
    }

    impl Month {
        /// Returns the month number in the range `1..=12`.
        #[inline]
        pub const fn number_from_month(self) -> u8 {
            self as u8 + 1
        }
    }

    impl fmt::Display for Month {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            let name = match self {
                Month::January => "January",
                Month::February => "February",
                Month::March => "March",
                Month::April => "April",
                Month::May => "May",
                Month::June => "June",
                Month::July => "July",
                Month::August => "August",
                Month::September => "September",
                Month::October => "October",
                Month::November => "November",
                Month::December => "December",
            };
            f.write_str(name)
        }
    }

    /// Error returned when a value falls outside the range of valid months.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct InvalidMonth(());

    impl fmt::Display for InvalidMonth {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str("month must be in the range 1..=12")
        }
    }

    impl Error for InvalidMonth {}

    impl TryFrom<u8> for Month {
        type Error = InvalidMonth;

        fn try_from(value: u8) -> Result<Month, Self::Error> {
            match value.checked_sub(1) {
                Some(0) => Ok(Month::January),
                Some(1) => Ok(Month::February),
                Some(2) => Ok(Month::March),
                Some(3) => Ok(Month::April),
                Some(4) => Ok(Month::May),
                Some(5) => Ok(Month::June),
                Some(6) => Ok(Month::July),
                Some(7) => Ok(Month::August),
                Some(8) => Ok(Month::September),
                Some(9) => Ok(Month::October),
                Some(10) => Ok(Month::November),
                Some(11) => Ok(Month::December),
                _ => Err(InvalidMonth(())),
            }
        }
    }

    impl TryFrom<i8> for Month {
        type Error = InvalidMonth;

        fn try_from(value: i8) -> Result<Month, Self::Error> {
            u8::try_from(value)
                .map_err(|_| InvalidMonth(()))
                .and_then(Month::try_from)
        }
    }

    impl From<Month> for u8 {
        #[inline]
        fn from(month: Month) -> u8 {
            month.number_from_month()
        }
    }

    impl From<Month> for i8 {
        #[inline]
        fn from(month: Month) -> i8 {
            month.number_from_month() as i8
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn date_round_trip() {
        let date = date_from_ymd(2025, 2, 24).unwrap();
        assert_eq!(date_to_string(&date), "2025-02-24");
        assert_eq!(date_from_str("2025-02-24").unwrap(), date);
    }

    #[test]
    fn date_from_str_rejects_invalid() {
        assert!(date_from_str("2025/02/24").is_err());
        assert!(date_from_str("2025-02").is_err());
        assert!(date_from_str("not a date").is_err());
    }

    #[test]
    fn month_numbers() {
        assert_eq!(month_number(Month::January), 1);
        assert_eq!(month_number(Month::February), 2);
        assert_eq!(month_number(Month::December), 12);
    }

    #[test]
    fn month_try_from_u8() {
        assert_eq!(Month::try_from(1u8), Ok(Month::January));
        assert_eq!(Month::try_from(12u8), Ok(Month::December));
        assert!(Month::try_from(0u8).is_err());
        assert!(Month::try_from(13u8).is_err());
    }
}

//! # Document Credentials

use serde::{Deserialize, Serialize};

use crate::{B64Url, EditableField, EditableFieldString, EditableFieldValue, Extension};

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", bound(deserialize = "E: Deserialize<'de>"))]
pub struct CustomFieldsCredential<E = ()> {
    /// A unique identifier for the CustomFields. It MUST be a machine-generated opaque byte
    /// sequence with a maximum size of 64 bytes. It SHOULD NOT be displayed to the user.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<B64Url>,
    /// This member is a [human-palatable](https://www.w3.org/TR/webauthn-3/#human-palatability)
    /// title to describe the section. This value MAY be set by the credential owner.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
    /// The collection of miscellaneous fields under this section.
    pub fields: Vec<EditableFieldValue<E>>,
    /// This member permits the exporting provider to add additional information associated to this
    /// CustomFields. This MAY be used to provide an exchange where a minimal amount of information
    /// is lost.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub extensions: Vec<Extension<E>>,
}

/// A [FileCredential] acts as a placeholder to an arbitrary binary file holding its associated
/// metadata. When an importing provider encounters a file credential, they MAY request the file
/// afterwards if they have a direct exchange. If the exchange will produce an export response file,
/// then the associated encrypted file MUST be stored in the documents folder of the zip archive.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileCredential {
    /// The file’s identifier, used as the file name in the zip archive.
    pub id: B64Url,
    /// The file name with the file extension if applicable.
    pub name: String,
    /// The file’s decrypted size in bytes.
    pub decrypted_size: u64,
    /// The SHA256 hash of the decrypted file. This hash MUST be used by the importing provider
    /// when the file is decrypted to ensure that it has not been corrupted.
    pub integrity_hash: B64Url,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", bound(deserialize = "E: Deserialize<'de>"))]
pub struct NoteCredential<E = ()> {
    /// This member is a user-defined value encoded as a UTF-8 string.
    pub content: EditableField<EditableFieldString, E>,
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;
    use crate::{EditableFieldBoolean, EditableFieldString, EditableFieldYearMonth, Month};

    #[test]
    fn test_serialize_custom_fields() {
        let credential = CustomFieldsCredential {
            id: None,
            label: None,
            fields: vec![
                EditableFieldValue::<()>::String(EditableField {
                    id: Some(B64Url::from(b"field1".as_slice())),
                    value: EditableFieldString("hello".into()).into(),
                    label: None,
                    extensions: None,
                }),
                EditableFieldValue::<()>::Boolean(EditableField {
                    id: None,
                    value: EditableFieldBoolean(false).into(),
                    label: None,
                    extensions: None,
                }),
            ],
            extensions: vec![],
        };

        let json = json!({
            "fields": [
                {
                    "id": "ZmllbGQx",
                    "fieldType": "string",
                    "value": "hello"
                },
                {
                    "fieldType": "boolean",
                    "value": "false"
                }
            ]
        });

        assert_eq!(serde_json::to_value(&credential).unwrap(), json);
    }

    #[test]
    fn test_deserialize_custom_fields() {
        let json = json!({
            "fields": [
                {
                    "fieldType": "string",
                    "value": "hello"
                },
                {
                    "fieldType": "concealed-string",
                    "value": "world"
                },
                {
                    "fieldType": "boolean",
                    "value": "false"
                },
                {
                    "fieldType": "year-month",
                    "value": "2025-02"
                }
            ]
        });

        let json = serde_json::to_string(&json).unwrap();
        let credential: CustomFieldsCredential = serde_json::from_str(&json).unwrap();

        assert_eq!(credential.id, None);
        assert_eq!(credential.label, None);
        assert_eq!(credential.extensions.len(), 0);
        assert_eq!(credential.fields.len(), 4);

        match &credential.fields[0] {
            EditableFieldValue::String(field) => {
                assert_eq!(field.value.as_expected().map(|v| v.0.as_str()), Ok("hello"));
            }
            _ => panic!("Expected string field"),
        }

        match &credential.fields[1] {
            EditableFieldValue::ConcealedString(field) => {
                assert_eq!(field.value.as_expected().map(|v| v.0.as_str()), Ok("world"));
            }
            _ => panic!("Expected concealed string field"),
        }

        match &credential.fields[2] {
            EditableFieldValue::Boolean(field) => {
                assert_eq!(field.value.as_expected().map(|e| e.0), Ok(false));
            }
            _ => panic!("Expected boolean field"),
        }

        match &credential.fields[3] {
            EditableFieldValue::YearMonth(field) => {
                assert_eq!(
                    field.value.as_expected(),
                    Ok(&EditableFieldYearMonth {
                        year: 2025,
                        month: Month::February,
                    })
                );
            }
            _ => panic!("Expected boolean field"),
        }
    }
}
